1	"use client";
2	
3	import Link from "next/link";
4	import { useEffect, useRef, useState, useTransition } from "react";
5	import { Badge, fmtMoney } from "@/components/ui/primitives";
6	import {
7	  orderEmailHosting,
8	  addMailbox,
9	  removeMailbox,
10	  revealMailboxPassword,
11	  resetMailboxPassword,
12	  retryMailboxProvision,
13	  checkEmailDeliverability,
14	} from "@/lib/actions-email-hosting";
15	import type { DeliverabilityReport, CheckStatus } from "@/lib/mail/deliverability";
16	import { EmailDnsSetup } from "@/components/customer/EmailDnsSetup";
17	import { ANNUAL_TERM_MONTHS, termPriceCents, termDiscountPct, vpsEffectiveMonthly, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
18	import { TermLadder } from "@/components/customer/TermLadder";
19	import { PaymentStep } from "@/components/customer/PaymentStep";
20	import { WizardReassuranceCard } from "@/components/customer/WizardReassuranceCard";
21	import { WizardStickyCart } from "@/components/customer/WizardStickyCart";
22	import { walletSplit } from "@/lib/wallet-split";
23	import { trackDeployStep, trackDeployError } from "@/lib/deploy-funnel-client";
24	
25	export type PlanOpt = {
26	  id: string;
27	  name: string;
28	  mailboxes: number;
29	  storageGB: number;
30	  priceCents: number;
31	  termMonths: number;
32	};
33	
34	export type MailboxRow = {
35	  id: string;
36	  address: string;
37	  /** Mailbox.status — PROVISIONING | ACTIVE | FAILED | SUSPENDED. */
38	  status: string;
39	  createdAt: string;
40	};
41	
42	export type SubscriptionRow = {
43	  id: string;
44	  domainName: string;
45	  status: string;
46	  external: boolean;
47	  verified: boolean;
48	  planName: string;
49	  planMailboxes: number;
50	  planStorageGB: number;
51	  expiresAt: string | null;
52	  mailboxes: MailboxRow[];
53	};
54	
55	export function EmailHosting({
56	  domains,
57	  plans,
58	  subscriptions,
59	  balanceCents,
60	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
61	  showSubscriptions = true,
62	  email,
63	}: {
64	  domains: string[];
65	  plans: PlanOpt[];
66	  subscriptions: SubscriptionRow[];
67	  balanceCents: number;
68	  /** Live admin annual discount (%), so the Annual term shows the REAL price/savings. */
69	  annualDiscountPct?: number;
70	  /**
71	   * Whether to render the "Your email subscriptions" management list. The Deploy hub
72	   * sets this false so the deploy page stays an ORDER surface (add email hosting) —
73	   * the full subscription/mailbox management lives on /dashboard/email.
74	   */
75	  showSubscriptions?: boolean;
76	  /** The account's email — PaymentStep's receipt/invoice-email display, same as
77	   *  the VPS/Game/Hosting wizards. */
78	  email: string;
79	}) {
80	  // Registered domains without a subscription are offered as quick suggestions,
81	  // but any domain (registered elsewhere) can be typed in too.
82	  const subbed = new Set(subscriptions.map((s) => s.domainName));
83	  const suggestedDomains = domains.filter((d) => !subbed.has(d));
84	
85	  return (
86	    <div className="space-y-8">
87	      <DnsPanel />
88	
89	      {plans.length > 0 && (
90	        <OrderPanel
91	          suggestedDomains={suggestedDomains}
92	          plans={plans}
93	          balanceCents={balanceCents}
94	          annualDiscountPct={annualDiscountPct}
95	          email={email}
96	        />
97	      )}
98	
99	      {showSubscriptions && (
100	        <section>
101	          <h2 className="mb-3 text-lg font-semibold text-white">Your email subscriptions</h2>
102	          {subscriptions.length === 0 ? (
103	            <div className="card text-sm text-slate-400">
104	              No email subscriptions yet. Pick a domain and a plan above to get started.
105	            </div>
106	          ) : (
107	            <div className="space-y-4">
108	              {subscriptions.map((s) => (
109	                <SubscriptionCard key={s.id} sub={s} />
110	              ))}
111	            </div>
112	          )}
113	        </section>
114	      )}
115	    </div>
116	  );
117	}
118	
119	/** MX / SPF guidance for domains registered outside Nxeon. */
120	function DnsPanel() {
121	  return (
122	    <div className="card border-white/[0.06]">
123	      <div className="flex flex-wrap items-center gap-2">
124	        <h2 className="text-lg font-semibold text-white">How Business Email works</h2>
125	      </div>
126	      <p className="mt-2 text-sm text-slate-300">
127	        Add email hosting to any domain — one registered with Nxeon, or one you own elsewhere. If the
128	        domain is in your account we configure DNS for you and mail is enabled straight away. For a
129	        domain registered elsewhere, add the DNS records we show on the subscription below and hit
130	        <span className="font-medium text-slate-200"> Verify DNS</span> — mail starts flowing once
131	        verification succeeds.
132	      </p>
133	      <div className="mt-3 flex flex-wrap items-center gap-3">
134	        <Link href="/dashboard/mail" className="btn-primary py-1 text-sm">
135	          Open inbox →
136	        </Link>
137	        <Link href="/dashboard/domains" className="btn-secondary py-1 text-sm">
138	          Manage domain DNS →
139	        </Link>
140	        <span className="text-xs text-slate-500">
141	          Read and send from your mailboxes right here in the portal — no separate app.
142	        </span>
143	      </div>
144	    </div>
145	  );
146	}
147	
148	/** Same visual step-tracker every other deploy wizard uses (VPS/Hosting/Game). */
149	function Stepper({ step, steps }: { step: number; steps: string[] }) {
150	  return (
151	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
152	      {steps.map((s, i) => (
153	        <div key={s} className="flex items-center gap-2">
154	          <span
155	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
156	              i === step
157	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
158	                : i < step
159	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
160	                  : "border-white/10 text-slate-500"
161	            }`}
162	          >
163	            {i < step ? "✓" : i + 1}
164	          </span>
165	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
166	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
167	        </div>
168	      ))}
169	    </div>
170	  );
171	}
172	
173	const ORDER_STEPS = ["Domain", "Plan", "Review"];
174	
175	function OrderPanel({
176	  suggestedDomains,
177	  plans,
178	  balanceCents,
179	  annualDiscountPct,
180	  email,
181	}: {
182	  suggestedDomains: string[];
183	  plans: PlanOpt[];
184	  balanceCents: number;
185	  annualDiscountPct: number;
186	  email: string;
187	}) {
188	  const [step, setStep] = useState(0);
189	  const [domain, setDomain] = useState(suggestedDomains[0] ?? "");
190	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
191	  // Annual is the recommended, better-value default; monthly stays one click away.
192	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
193	  const [error, setError] = useState<string | null>(null);
194	  const [ok, setOk] = useState(false);
195	  const [pending, start] = useTransition();
196	  // "Apply my balance" — mirrors the VPS/hosting wizards. Default ON when there's a
197	  // balance to apply; off routes the whole charge to a card. The server recomputes the
198	  // identical split (lib/wallet-split.ts), so displayed === charged.
199	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
200	  // Mirrors DeployWizard's stripePhase/checkoutSession split: "loading"/"error"
201	  // track the embedded Payment step's own session request; "ready" is implied
202	  // by checkoutSession being non-null.
203	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
204	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
205	  // Clicking "Change" next to the billing term inside PaymentStep's Order
206	  // Summary used to jump all the way back to the Plan step — reveals the same
207	  // TermLadder cards inline instead, right above the payment form, mirroring
208	  // DeployWizard's showTermPicker pattern exactly.
209	  const [showTermPicker, setShowTermPicker] = useState(false);
210	  const isLast = step === ORDER_STEPS.length - 1;
211	  const domainBlocker = !domain.trim() ? "Enter a domain to continue." : null;
212	
213	  // Deploy-funnel: record reaching each wizard step (de-duped per session in the
214	  // helper) so the admin funnel shows how far people get. Mirrors DeployWizard.
215	  useEffect(() => {
216	    trackDeployStep("email", ORDER_STEPS[step] ?? String(step), step);
217	    // eslint-disable-next-line react-hooks/exhaustive-deps
218	  }, [step]);
219	
220	  // Deploy-funnel: when the order action returns an error, record it against the
221	  // current step so a BUG is distinguishable from abandonment.
222	  useEffect(() => {
223	    if (error) trackDeployError("email", ORDER_STEPS[step] ?? "Review", step, "ORDER_ERROR", error);
224	    // eslint-disable-next-line react-hooks/exhaustive-deps
225	  }, [error]);
226	
227	  const selected = plans.find((p) => p.id === planId);
228	  // Email plans are seeded monthly, so priceCents is the per-month base. Price the
229	  // chosen term through the SAME formula the server charges (termPriceCents).
230	  const termCharge = selected ? termPriceCents(selected.priceCents, termMonths, annualDiscountPct) : 0;
231	  // Same rate the term charge above was computed with — shown next to the
232	  // billing term as a "Save X%" badge (DeployWizard's termDiscountPct pattern).
233	  const discountPercent = termDiscountPct(termMonths, annualDiscountPct);
234	  // Business Email has no first-month-free, so the amount due today IS the term charge.
235	  const split = walletSplit({ dueCents: termCharge, balanceCents, useWallet });
236	  const cardCents = split.cardCents;
237	  const walletApplied = split.walletApplied;
238	  const registered = new Set(suggestedDomains.map((d) => d.toLowerCase()));
239	  const trimmed = domain.trim().toLowerCase();
240	  const isExternal = trimmed.length > 0 && !registered.has(trimmed);
241	
242	  function submit() {
243	    if (!domain.trim()) {
244	      setError("Enter a domain.");
245	      return;
246	    }
247	    setError(null);
248	    setOk(false);
249	    setStripePhase("loading");
250	    // Deploy-funnel: the customer submitted the final Review, so a wallet charge
251	    // or a Stripe checkout session is about to be attempted — record REACHED-
252	    // PAYMENT as a step at the tail (after Review). De-duped per session in the
253	    // helper; completion is recorded server-side (see orderEmailHostingCore).
254	    trackDeployStep("email", "Payment", ORDER_STEPS.length);
255	    start(async () => {
256	      const res = await orderEmailHosting(domain.trim(), planId, termMonths, useWallet);
257	      // A card leg is due — mount the embedded Payment step. On success Stripe
258	      // navigates the top window to the confirm route, which credits the card to the
259	      // wallet and creates the subscription.
260	      if (res && "checkout" in res) {
261	        setCheckoutSession({ clientSecret: res.checkout.clientSecret, publishableKey: res.checkout.publishableKey });
262	        setStripePhase("idle");
263	        return;
264	      }
265	      if (res?.error) {
266	        setError(res.error);
267	        setStripePhase("error");
268	      } else if (res?.ok) {
269	        setOk(true);
270	        // Fire-and-forget "email" conversion (→ Meta Subscribe + the Google Ads
271	        // email label). Best-effort: a no-op until consent + the pixel load.
272	        try {
273	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("email", { value: termCharge / 100, currency: "USD" });
274	        } catch {
275	          /* ignore */
276	        }
277	      }
278	    });
279	  }
280	
281	  // A card leg is due once the customer reaches Review — same condition VPS
282	  // uses to decide whether PaymentStep mounts instead of the plain fallback.
283	  const showPaymentStep = isLast && cardCents > 0;
284	
285	  // A Custom Checkout session is priced at the moment it's created. If the
286	  // customer flips "Apply my balance" AFTER one exists, its stamped amount is
287	  // stale — drop it so PaymentStep asks for a fresh one, rather than letting
288	  // them confirm a payment for the wrong total. Same guard DeployWizard uses.
289	  const prevCardCentsRef = useRef(cardCents);
290	  useEffect(() => {
291	    if (checkoutSession && prevCardCentsRef.current !== cardCents) {
292	      setCheckoutSession(null);
293	      setStripePhase("idle");
294	    }
295	    prevCardCentsRef.current = cardCents;
296	  }, [cardCents, checkoutSession]);
297	
298	  // PaymentStep's PayPal/Coinbase support isn't wired for Business Email yet
299	  // (no product need identified) — these stubs are never invoked since
300	  // `paypal`/`coinbaseReady` are both off, which hides those method rows
301	  // entirely.
302	  async function paypalUnavailable() {
303	    return { error: "PayPal isn't available for Business Email yet." };
304	  }
305	
306	  return (
307	    <section>
308	      <div className="card wizard-shell space-y-4">
309	        <Stepper step={step} steps={ORDER_STEPS} />
310	
311	        {error && (
312	          <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
313	            {error}
314	          </div>
315	        )}
316	        {ok && (
317	          <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
318	            Subscription created. Add mailboxes below — and, for a domain registered elsewhere, finish
319	            the DNS setup shown on the subscription.
320	          </div>
321	        )}
322	
323	        {/* Step 1 — Domain */}
324	        {step === 0 && (
325	          <div>
326	            <label className="label">Domain</label>
327	            <input
328	              className="input"
329	              value={domain}
330	              onChange={(e) => setDomain(e.target.value)}
331	              placeholder="yourdomain.com"
332	              list="nxeon-email-domains"
333	              autoCapitalize="none"
334	              autoCorrect="off"
335	              spellCheck={false}
336	            />
337	            <datalist id="nxeon-email-domains">
338	              {suggestedDomains.map((d) => (
339	                <option key={d} value={d} />
340	              ))}
341	            </datalist>
342	            <p className="mt-1 text-xs text-slate-500">
343	              {isExternal
344	                ? "Registered elsewhere — you'll add DNS records and verify after ordering."
345	                : "In your account — DNS is configured for you."}
346	            </p>
347	
348	            {/* A couple of lines of plain-English context for anyone who's never
349	                touched MX records or DNS verification before — what actually
350	                happens for each kind of domain, not just the one-line status
351	                above. Icon+short-caption pairing mirrors WizardReassuranceCard's
352	                convention rather than inventing a new one. */}
353	            <div className="mt-4 grid gap-3 sm:grid-cols-2">
354	              <div className="flex items-start gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
355	                <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-brand-500/10 text-brand-300">
356	                  <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
357	                    <path d="M9 12.2l2 2 4-4.2" />
358	                    <circle cx="12" cy="12" r="9" />
359	                  </svg>
360	                </span>
361	                <p className="text-xs text-slate-400">
362	                  <span className="font-medium text-slate-200">A domain in your account</span> works instantly — we
363	                  point its mail records (MX) at our servers for you, so there&apos;s nothing to configure.
364	                </p>
365	              </div>
366	              <div className="flex items-start gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
367	                <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-brand-500/10 text-brand-300">
368	                  <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
369	                    <rect x="3" y="4" width="18" height="16" rx="2" />
370	                    <path d="m3 8 9 6 9-6" />
371	                  </svg>
372	                </span>
373	                <p className="text-xs text-slate-400">
374	                  <span className="font-medium text-slate-200">A domain registered elsewhere</span> still works — after
375	                  ordering, we&apos;ll show you a couple of DNS records to add there. Mail starts flowing once we
376	                  verify they&apos;re published.
377	                </p>
378	              </div>
379	            </div>
380	          </div>
381	        )}
382	
383	        {/* Step 2 — Plan & billing term */}
384	        {step === 1 && (
385	          <div className="space-y-4">
386	            <div>
387	              <label className="label mb-2 block">Plan</label>
388	              <div className="grid gap-3 sm:grid-cols-3">
389	                {plans.map((p, i) => (
390	                  <button
391	                    type="button"
392	                    key={p.id}
393	                    onClick={() => setPlanId(p.id)}
394	                    className={`card p-4 text-left transition ${
395	                      planId === p.id ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
396	                    }`}
397	                  >
398	                    <div className="flex items-center justify-between">
399	                      <span className="font-semibold">{p.name}</span>
400	                      {i === Math.floor(plans.length / 2) && (
401	                        <span className="rounded-full bg-brand-500/20 px-2 py-0.5 text-[10px] text-brand-200">popular</span>
402	                      )}
403	                    </div>
404	                    <p className="mt-1 flex items-baseline gap-1.5">
405	                      <span className="text-2xl font-bold">{fmtMoney(p.priceCents)}</span>
406	                      <span className="text-xs font-normal text-slate-400">/mo</span>
407	                    </p>
408	                    <p className="text-[11px] text-slate-500">
409	                      {p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · {p.storageGB} GB each
410	                    </p>
411	                  </button>
412	                ))}
413	              </div>
414	            </div>
415	
416	            {selected && (
417	              <div>
418	                <div className="mb-1.5 flex items-baseline justify-between gap-2">
419	                  <label className="label mb-0">Billing term</label>
420	                  <span className="text-[11px] text-slate-500">Commit longer, pay less per month</span>
421	                </div>
422	                <TermLadder
423	                  monthlyCents={selected.priceCents}
424	                  annualDiscountPct={annualDiscountPct}
425	                  value={termMonths}
426	                  onChange={setTermMonths}
427	                  size="sm"
428	                />
429	                <div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.06] px-3 py-2 text-sm">
430	                  <span className="text-slate-300">
431	                    {selected.mailboxes} mailbox{selected.mailboxes === 1 ? "" : "es"} · {selected.storageGB} GB each
432	                  </span>
433	                  <span className="text-white">
434	                    {fmtMoney(termCharge)}
435	                    {termMonths > 1 ? ` / ${termMonths} mo` : " / mo"}
436	                  </span>
437	                </div>
438	              </div>
439	            )}
440	          </div>
441	        )}
442	
443	        {/* Step 3 — Review & pay. Once a card leg is due, PaymentStep owns the
444	            entire review + payment surface (Order Summary, wallet toggle,
445	            billing-term line) — the plain dl below is the fallback for the
446	            wallet-only / $0-card path, where PaymentStep never mounts. */}
447	        {step === 2 && !showPaymentStep && (
448	          <div className="space-y-3">
449	            <dl className="space-y-2 text-sm">
450	              <div className="flex items-center justify-between">
451	                <dt className="text-slate-400">Domain</dt>
452	                <dd className="text-slate-200">{domain || "—"}</dd>
453	              </div>
454	              {selected && (
455	                <div className="flex items-center justify-between">
456	                  <dt className="text-slate-400">Plan</dt>
457	                  <dd className="text-slate-200">
458	                    {selected.name} · {selected.mailboxes} mailbox{selected.mailboxes === 1 ? "" : "es"} ·{" "}
459	                    {selected.storageGB} GB each
460	                  </dd>
461	                </div>
462	              )}
463	              <div className="flex items-center justify-between">
464	                <dt className="text-slate-400">Billing term</dt>
465	                <dd className="flex items-center gap-2 text-slate-200">
466	                  {termMonths === 1 ? "Monthly" : `Every ${termMonths} mo`}
467	                  {discountPercent > 0 && <span className="text-emerald-300">Save {discountPercent}%</span>}
468	                  <button type="button" onClick={() => setStep(1)} className="text-xs font-medium text-brand-300 hover:text-brand-200">
469	                    Change
470	                  </button>
471	                </dd>
472	              </div>
473	              <div className="divider" />
474	              <div className="flex items-center justify-between">
475	                <dt className="text-slate-400">Due today</dt>
476	                <dd className="text-base font-semibold text-white">{fmtMoney(termCharge)}</dd>
477	              </div>
478	            </dl>
479	
480	            {termCharge > 0 && balanceCents > 0 && (
481	              <label className="flex items-center justify-between gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
482	                <span className="flex items-center gap-2 text-slate-300">
483	                  <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
484	                  Apply my balance ({fmtMoney(balanceCents)})
485	                </span>
486	                <span className="text-xs text-slate-500">{useWallet ? "applied" : "off"}</span>
487	              </label>
488	            )}
489	            {termCharge > 0 && (
490	              <div className="flex flex-wrap items-center justify-between gap-2 text-sm">
491	                {walletApplied > 0 && <span className="text-emerald-300">Wallet credit −{fmtMoney(walletApplied)}</span>}
492	                <span className="ml-auto text-slate-300">
493	                  {cardCents > 0 ? "Pay by card" : "Paid from wallet"}:{" "}
494	                  <span className="font-semibold text-white">{cardCents > 0 ? fmtMoney(cardCents) : "$0 card"}</span>
495	                </span>
496	              </div>
497	            )}
498	            {split.clampedForStripeMin && (
499	              <p className="text-xs text-amber-300">Card payments have a {fmtMoney(50)} minimum, so we&apos;ll charge {fmtMoney(cardCents)} to your card and apply the rest ({fmtMoney(walletApplied)}) from your wallet.</p>
500	            )}
501	            <p className="text-xs text-slate-500">
502	              Wallet balance: <span className="text-slate-300">{fmtMoney(balanceCents)}</span>
503	            </p>
504	          </div>
505	        )}
506	
507	        {step === 2 && showPaymentStep && (
508	          <>
509	            {/*
510	              Clicking "Change" next to the billing term inside PaymentStep's
511	              Order Summary used to jump all the way back to the Plan step —
512	              real customer feedback was that this felt like losing your place
513	              on the LAST step of the wizard. Reveals the same TermLadder cards
514	              inline instead, right above the payment form, exactly mirroring
515	              DeployWizard's showTermPicker pattern.
516	            */}
517	            {showTermPicker && selected && (
