/**
 * Why a subscription needs the customer's attention right now — surfaced so it
 * can be sorted to the top and auto-expanded instead of getting the same visual
 * weight (and default-collapsed treatment) as one that's already fully set up.
 */
function attentionReason(sub: SubscriptionRow): "dns" | "failed" | null {
  if (sub.external && !sub.verified) return "dns";
  if (sub.mailboxes.some((m) => m.status === "FAILED")) return "failed";
  return null;
}

/** attention: needs a customer action · active: set up and has mailboxes ·
 *  empty: nothing blocking, just hasn't had a mailbox added yet. */
function categoryOf(sub: SubscriptionRow): "attention" | "active" | "empty" {
  if (attentionReason(sub)) return "attention";
  return sub.mailboxes.length === 0 ? "empty" : "active";
}

const CATEGORY_RANK: Record<ReturnType<typeof categoryOf>, number> = {
  attention: 0,
  active: 1,
  empty: 2,
};

/** Same pill-filter convention as ServersList.tsx — active/count chips, click
 *  again to clear back to "All". */
function FilterChip({
  label,
  count,
  active,
  onClick,
}: {
  label: string;
  count: number;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors ${
        active
          ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
          : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-white"
      }`}
    >
      {label} · {count}
    </button>
  );
}

type SubFilter = "ALL" | "attention" | "active" | "empty";

/**
 * The reorganized subscriptions list — replaces "every subscription fully
 * expanded, in one long column" with:
 *   - filter chips (ServersList's established pill convention) so a customer
 *     with many domains can jump straight to the ones that need setup;
 *   - a domain search box, once there are enough subscriptions for one to earn
 *     its place on screen;
 *   - subscriptions needing attention (unverified DNS, a failed mailbox)
 *     sorted first; fully-empty "not set up yet" ones sorted last so they
 *     don't take the same prime real estate as an active domain.
 * Each subscription still renders through SubscriptionCard — nothing about
 * the underlying data or actions changes, only default expand/collapse and
 * ordering.
 */
function SubscriptionsList({ subscriptions }: { subscriptions: SubscriptionRow[] }) {
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<SubFilter>("ALL");

  const categorized = useMemo(
    () => subscriptions.map((sub) => ({ sub, category: categoryOf(sub) })),
    [subscriptions],
  );

  const counts = useMemo(() => {
    const c = { attention: 0, active: 0, empty: 0 };
    for (const { category } of categorized) c[category]++;
    return c;
  }, [categorized]);

  const q = query.trim().toLowerCase();
  const searched = q ? categorized.filter(({ sub }) => sub.domainName.toLowerCase().includes(q)) : categorized;
  const filtered = filter === "ALL" ? searched : searched.filter((x) => x.category === filter);
  // Array.prototype.sort is stable (ES2019+), so this only groups — it never
  // reorders two subscriptions within the same category relative to each other.
  const ordered = [...filtered].sort((a, b) => CATEGORY_RANK[a.category] - CATEGORY_RANK[b.category]);

  // A handful of subscriptions isn't the clutter problem this is solving —
  // showing search/filter chrome over 2-3 cards would just be more clutter.
  const showToolbar = subscriptions.length > 3;

  return (
    <div className="space-y-4">
      {showToolbar && (
        <div className="flex flex-wrap items-center gap-2">
          <FilterChip label="All" count={subscriptions.length} active={filter === "ALL"} onClick={() => setFilter("ALL")} />
          {counts.attention > 0 && (
            <FilterChip
              label="Needs attention"
              count={counts.attention}
              active={filter === "attention"}
              onClick={() => setFilter((f) => (f === "attention" ? "ALL" : "attention"))}
            />
          )}
          {counts.active > 0 && (
            <FilterChip
              label="Active"
              count={counts.active}
              active={filter === "active"}
              onClick={() => setFilter((f) => (f === "active" ? "ALL" : "active"))}
            />
          )}
          {counts.empty > 0 && (
            <FilterChip
              label="Not set up yet"
              count={counts.empty}
              active={filter === "empty"}
              onClick={() => setFilter((f) => (f === "empty" ? "ALL" : "empty"))}
            />
          )}
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search by domain…"
            className="input ml-auto w-full max-w-[220px] py-1.5 text-sm"
            aria-label="Search subscriptions by domain"
          />
        </div>
      )}

      {ordered.length === 0 ? (
        <div className="card flex flex-wrap items-center justify-between gap-3 text-sm text-slate-400">
          <span>No subscriptions match {query ? `“${query}”` : "this filter"}.</span>
          <button
            type="button"
            className="btn-ghost py-1 text-xs"
            onClick={() => {
              setQuery("");
              setFilter("ALL");
            }}
          >
            Clear
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {ordered.map(({ sub }) => (
            <SubscriptionCard
              key={sub.id}
              sub={sub}
              // Auto-expand what needs action. Otherwise, a tiny account (1-2
              // subscriptions) gets no collapsing at all — there's nothing to
              // declutter — while a bigger one defaults to collapsed so the
              // page reads as a scannable list, not a wall of cards.
              defaultExpanded={attentionReason(sub) !== null || subscriptions.length <= 2}
            />
          ))}
        </div>
      )}
    </div>
  );
}

/** Chevron used on the collapsible subscription header. */
function ChevronIcon({ open }: { open: boolean }) {
  return (
    <svg
      viewBox="0 0 24 24"
      width="16"
      height="16"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className={`shrink-0 text-slate-500 transition-transform duration-150 ${open ? "rotate-180" : ""}`}
    >
      <path d="M6 9l6 6 6-6" />
    </svg>
  );
}

function SubscriptionCard({ sub, defaultExpanded }: { sub: SubscriptionRow; defaultExpanded: boolean }) {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const atLimit = sub.mailboxes.length >= sub.planMailboxes;
  const reason = attentionReason(sub);
  const panelId = `email-sub-panel-${sub.id}`;

  return (
    <div className="card card-hover p-0">
      {/* The whole header is one real <button> — keyboard-operable expand/collapse,
          no nested interactive elements (the badges below are plain spans). */}
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
        aria-controls={panelId}
        className="flex w-full items-center gap-3 rounded-2xl px-6 py-4 text-left transition-colors hover:bg-white/[0.02]"
      >
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <span className="font-semibold text-white">{sub.domainName}</span>
            <Badge tone={sub.status === "ACTIVE" ? "green" : "slate"}>{sub.status}</Badge>
            {sub.external ? (
              sub.verified ? (
                <Badge tone="green">Verified</Badge>
              ) : (
                <Badge tone="amber">Setup required</Badge>
              )
            ) : (
              <Badge tone="slate">Managed by Nxeon</Badge>
            )}
            {reason === "failed" && <Badge tone="red">Mailbox setup failed</Badge>}
          </div>
          <p className="mt-1 text-sm text-slate-400">
            {sub.planName} · {sub.mailboxes.length}/{sub.planMailboxes} mailbox
            {sub.planMailboxes === 1 ? "" : "es"} used · {sub.planStorageGB} GB each
            {sub.expiresAt && ` · renews ${new Date(sub.expiresAt).toLocaleDateString()}`}
          </p>
        </div>
        <ChevronIcon open={expanded} />
      </button>

      {expanded && (
        <div id={panelId} className="border-t border-white/[0.06] px-6 pb-6 pt-4">
          {sub.external ? (
            <EmailDnsSetup
              subscriptionId={sub.id}
              domainName={sub.domainName}
              verified={sub.verified}
            />
          ) : (
            <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
              This domain is registered with Nxeon, so its mail DNS is managed for you — mailboxes go live
              automatically. Run the deliverability check below to confirm every record is actually published.
            </div>
          )}

          <DeliverabilityPanel subscriptionId={sub.id} domainName={sub.domainName} />

          <div className="mt-4">
            <h3 className="mb-2 text-sm font-semibold text-slate-200">Mailboxes</h3>
            {sub.mailboxes.length === 0 ? (
              <p className="text-sm text-slate-500">No mailboxes yet — add your first below.</p>
            ) : (
              <div className="space-y-2">
                {sub.mailboxes.map((m) => (
                  <MailboxItem key={m.id} mailbox={m} />
                ))}
              </div>
            )}
          </div>

          <AddMailboxForm subscriptionId={sub.id} domainName={sub.domainName} atLimit={atLimit} />
        </div>
      )}
    </div>
  );
}

/**
 * 3-dot action menu — same outside-click/Escape-to-close + `rounded-xl border
 * border-white/10 bg-navy-950/95 shadow-2xl backdrop-blur-xl` dropdown chrome
 * CurrencySwitcher already established for this codebase, reused here instead
 * of inventing a new menu pattern. Holds the less-common per-mailbox actions
 * (Show/Reset password, Remove) so "Open inbox" stays the one visible primary
 * action per row instead of four buttons competing for attention.
 */
function RowMenu({
  items,
  label = "More actions",
}: {
  items: { label: string; onClick: () => void; danger?: boolean; disabled?: boolean }[];
  label?: string;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={label}
        className="btn-secondary flex h-7 w-7 items-center justify-center p-0 text-xs"
      >
        <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden>
          <circle cx="5" cy="12" r="1.8" />
          <circle cx="12" cy="12" r="1.8" />
          <circle cx="19" cy="12" r="1.8" />
        </svg>
      </button>
      {open && (
        <div
          role="menu"
          aria-label={label}
          className="absolute right-0 z-20 mt-1.5 w-48 overflow-hidden rounded-xl border border-white/10 bg-navy-950/95 py-1 shadow-2xl backdrop-blur-xl"
        >
          {items.map((it) => (
            <button
              key={it.label}
              type="button"
              role="menuitem"
              disabled={it.disabled}
              onClick={() => {
                setOpen(false);
                it.onClick();
              }}
              className={`block w-full px-3 py-2 text-left text-xs transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${
                it.danger ? "text-red-400 hover:bg-red-500/10" : "text-slate-200 hover:bg-white/[0.06]"
              }`}
            >
              {it.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

