const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();

  // Desktop
  const desktopPage = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  await desktopPage.goto('http://localhost:3971/preview-mailboxes', { waitUntil: 'networkidle' });
  await desktopPage.screenshot({ path: '/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/desktop-default.png', fullPage: true });

  // Click "Needs attention" filter chip
  const attnChip = desktopPage.locator('button:has-text("Needs attention")').first();
  if (await attnChip.count()) {
    await attnChip.click();
    await desktopPage.screenshot({ path: '/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/desktop-filtered-attention.png', fullPage: true });
    await attnChip.click(); // toggle back to ALL
  }

  // Search
  const search = desktopPage.locator('input[type="search"]').first();
  if (await search.count()) {
    await search.fill('kodely');
    await desktopPage.screenshot({ path: '/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/desktop-search.png', fullPage: true });
    await search.fill('');
  }

  // Expand an active subscription with mailboxes (kaymo.revsports.ca) to check
  // the mailbox rows + 3-dot menu.
  const kaymoHeader = desktopPage.locator('button:has-text("kaymo.revsports.ca")').first();
  await kaymoHeader.click();
  await desktopPage.waitForTimeout(300);
  await desktopPage.screenshot({ path: '/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/desktop-expanded-active.png', fullPage: true });

  // Open the 3-dot menu on the first mailbox row within that panel
  const moreBtn = desktopPage.locator('button[aria-label*="More actions for"]').first();
  await moreBtn.click();
  await desktopPage.waitForTimeout(200);
  await desktopPage.screenshot({ path: '/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/desktop-row-menu-open.png', fullPage: false });

  await desktopPage.close();

  // Mobile
  const mobilePage = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await mobilePage.goto('http://localhost:3971/preview-mailboxes', { waitUntil: 'networkidle' });
  await mobilePage.screenshot({ path: '/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/mobile-default.png', fullPage: true });

  await browser.close();
  console.log('done');
})();
